class Dinic:
 def __init__(self,n):self.g=[[] for _ in range(n)]
 def add(self,u,v,c):
  a=[v,c,None];b=[u,0,a];a[2]=b;self.g[u].append(a);self.g[v].append(b);return a
 def flow(self,s,t,limit=10**9):
  total=0;n=len(self.g)
  while total<limit:
   level=[-1]*n;level[s]=0;q=collections.deque([s])
   while q:
    u=q.popleft()
    for v,c,rev in self.g[u]:
     if c and level[v]<0:level[v]=level[u]+1;q.append(v)
   if level[t]<0:break
   it=[0]*n
   def dfs(u,f):
    if u==t:return f
    while it[u]<len(self.g[u]):
     e=self.g[u][it[u]];v,c,rev=e
     if c and level[v]==level[u]+1:
      z=dfs(v,min(f,c))
      if z:e[1]-=z;rev[1]+=z;return z
     it[u]+=1
    return 0
   while total<limit:
    z=dfs(s,limit-total)
    if not z:break
    total+=z
  return total

